import type { AgentMessage } from "@earendil-works/pi-agent-core";
import type { ImageContent, TextContent } from "@earendil-works/pi-ai";
import {
	convertToLlm,
	estimateTokens,
	serializeConversation,
	sessionEntryToContextMessages,
	type CompactionResult,
	type InlineExtension,
	type SessionBeforeCompactEvent,
	type SessionEntry,
} from "@earendil-works/pi-coding-agent";
import { CONTEXT_IMAGE_TOKEN_ESTIMATE } from "../token-packer.ts";
import {
	isTelegramContextDetails,
	projectTelegramContext,
	TELEGRAM_CONTEXT_TYPE,
	type TelegramContextImageResolver,
} from "./context.ts";

type SessionBeforeCompactResult = { cancel?: boolean; compaction?: CompactionResult };

export function serializeCompactionMessages(messages: AgentMessage[]): string {
	return serializeConversation(convertToLlm(withoutThinking(messages)));
}

/** The bot's private reasoning is speculation; a summary must only record what the group said. */
function withoutThinking(messages: AgentMessage[]): AgentMessage[] {
	return messages.map((message) =>
		message.role === "assistant"
			? { ...message, content: message.content.filter((block) => block.type !== "thinking") }
			: message,
	);
}

/** Preserve image/text order inside the transcript, without the ephemeral sticker catalog. */
export function buildCompactionContent(
	messages: AgentMessage[],
	previousSummary?: string,
	resolveImage?: TelegramContextImageResolver,
): string | (TextContent | ImageContent)[] {
	const ending =
		`\n</conversation>\n\n` +
		(previousSummary
			? `<previous-summary>\n${previousSummary}\n</previous-summary>\n\n把上面的旧摘要与新内容合并成一份更新的摘要。`
			: "请输出摘要。");
	if (!resolveImage) return `<conversation>\n${serializeCompactionMessages(messages)}${ending}`;
	const projected = convertToLlm(projectTelegramContext(withoutThinking(messages), resolveImage, false));
	const content: (TextContent | ImageContent)[] = [];
	const text = (value: string) => {
		const last = content.at(-1);
		if (last?.type === "text") last.text += value;
		else content.push({ type: "text", text: value });
	};
	text("<conversation>\n");
	for (const message of projected) {
		if (message.role === "user" && Array.isArray(message.content) && message.content.some((b) => b.type === "image")) {
			text("[User]: ");
			for (const block of message.content) {
				if (block.type === "text") text(block.text);
				else if (block.type === "image") content.push(block);
			}
		} else text(serializeConversation([message]));
		text("\n\n");
	}
	text(ending);
	return content;
}

function contextImageCount(entry: SessionEntry): number {
	if (entry.type !== "custom_message" || entry.customType !== TELEGRAM_CONTEXT_TYPE) return 0;
	if (!isTelegramContextDetails(entry.details)) return 0;
	let count = 0;
	for (const block of entry.details.blocks) if (block.type === "image") count++;
	return count;
}

/** Pi's own retained-window boundary: the previous compaction's kept start, else the branch start. */
function compactionBoundaryStart(entries: readonly SessionEntry[]): number {
	for (let index = entries.length - 1; index >= 0; index--) {
		const entry = entries[index]!;
		if (entry.type !== "compaction") continue;
		const kept = entries.findIndex((candidate) => candidate.id === entry.firstKeptEntryId);
		return kept >= 0 ? kept : index + 1;
	}
	return 0;
}

/**
 * Translate the image-inclusive retention budget into Pi's text-only units BEFORE Pi
 * prepares compaction. A before-compact handler is too late: Pi returns early if the
 * text fits, without ever emitting that event. Pi still owns valid cuts and split turns.
 */
export function compactionTextBudget(entries: readonly SessionEntry[], keepRecentTokens: number): number {
	const boundaryStart = compactionBoundaryStart(entries);
	let piTokens = 0;
	let chargedTokens = 0;
	let images = 0;
	for (let index = entries.length - 1; index >= boundaryStart && chargedTokens < keepRecentTokens; index--) {
		const entry = entries[index]!;
		const entryImages = contextImageCount(entry);
		const entryTokens = sessionEntryToContextMessages(entry).reduce((sum, message) => sum + estimateTokens(message), 0);
		piTokens += entryTokens;
		images += entryImages;
		chargedTokens += entryTokens + entryImages * CONTEXT_IMAGE_TOKEN_ESTIMATE;
	}
	return images > 0 && chargedTokens >= keepRecentTokens
		? Math.min(keepRecentTokens, Math.max(1, piTokens))
		: keepRecentTokens;
}

export function makeTelegramCompactionExtension(
	handle: (event: SessionBeforeCompactEvent) => Promise<SessionBeforeCompactResult>,
): InlineExtension {
	return {
		name: "tg-compaction",
		hidden: true,
		factory: (pi) => {
			pi.on("session_before_compact", handle);
		},
	};
}

import type { InlineExtension } from "@earendil-works/pi-coding-agent";
import { createHmac } from "node:crypto";
import { CONTEXT_IMAGE_TOKEN_ESTIMATE } from "../token-packer.ts";

/** Pi wraps compaction summaries with this prefix (core/messages.ts, not exported since 0.87). */
export const COMPACTION_SUMMARY_PREFIX =
	"The conversation history before this point was compacted into the following summary:";

export interface ProviderPayloadObservation {
	systemHash: string;
	toolsHash: string;
	messageHashes: string[];
	fullPayloadHash: string;
	firstDivergentSegment: "system" | "tools" | "messages" | "payload" | null;
	firstDivergentMessageIndex: number | null;
	firstDivergentByteOffset: number | null;
	tokenEstimate: {
		system: number;
		tools: number;
		compactedHistory: number;
		messages: number;
	};
}

// Diagnostic estimate for telemetry only; the hard budget upper bound is
// estimateProviderTokensUpperBound in ../token-packer.ts (kept separate: different semantics).
function tokenEstimate(value: unknown): number {
	// Image content parts carry base64 data URLs: raw byte size would dwarf every text
	// segment and collapse the scaled system/tools breakdown to zero, so charge the same
	// flat per-image budget the packer uses.
	if (isImageContentPart(value)) return CONTEXT_IMAGE_TOKEN_ESTIMATE;
	if (Array.isArray(value)) return value.reduce<number>((sum, entry) => sum + tokenEstimate(entry), 0);
	if (value && typeof value === "object") {
		return Object.values(value).reduce<number>((sum, entry) => sum + tokenEstimate(entry), 0);
	}
	return Math.max(0, Math.round(Buffer.byteLength(canonicalJson(value), "utf8") / 2));
}

// Image parts may use Pi data/mimeType, image_url (chat completions),
// input_image (responses), or image + base64 source (Anthropic messages).
function isImageContentPart(value: unknown): boolean {
	if (!value || typeof value !== "object" || Array.isArray(value)) return false;
	const record = value as Record<string, unknown>;
	if (record.type === "image_url" || record.type === "input_image") return true;
	if (record.type !== "image") return false;
	if (typeof record.data === "string") return true;
	const source = record.source;
	return (
		source != null &&
		typeof source === "object" &&
		!Array.isArray(source) &&
		typeof (source as Record<string, unknown>).data === "string"
	);
}

function containsCompactionSummary(value: unknown): boolean {
	if (typeof value === "string") return value.includes(COMPACTION_SUMMARY_PREFIX);
	if (Array.isArray(value)) return value.some(containsCompactionSummary);
	return Boolean(value && typeof value === "object" && Object.values(value).some(containsCompactionSummary));
}

export interface PreviousProviderPayloadFingerprint {
	systemHash: string;
	toolsHash: string;
	messageHashes: readonly string[];
	contextTokens: number;
}

/** Potential provider reuse when the previous raw prompt is an exact prefix of the current one. */
export function estimateCacheReadFromPrefix(
	current: ProviderPayloadObservation,
	previous: PreviousProviderPayloadFingerprint,
	currentContextTokens: number,
): number | null {
	if (
		!Number.isSafeInteger(previous.contextTokens) ||
		previous.contextTokens <= 0 ||
		!Number.isSafeInteger(currentContextTokens) ||
		currentContextTokens < previous.contextTokens ||
		current.systemHash !== previous.systemHash ||
		current.toolsHash !== previous.toolsHash ||
		previous.messageHashes.length > current.messageHashes.length
	) {
		return null;
	}
	for (let index = 0; index < previous.messageHashes.length; index++) {
		if (previous.messageHashes[index] !== current.messageHashes[index]) return null;
	}
	return previous.contextTokens;
}

const PAYLOAD_SNAPSHOT = Symbol("payload-snapshot");

interface PayloadSnapshot {
	systemJson: string;
	toolsJson: string;
	messageJson: string[];
	fullJson: string;
}

type ObservationWithSnapshot = ProviderPayloadObservation & { [PAYLOAD_SNAPSHOT]?: PayloadSnapshot };

function canonicalValue(value: unknown): unknown {
	if (value === null || typeof value === "string" || typeof value === "boolean") return value;
	if (typeof value === "number") return Number.isFinite(value) ? value : String(value);
	if (typeof value === "bigint") return value.toString();
	if (Array.isArray(value)) return value.map(canonicalValue);
	if (value && typeof value === "object") {
		return Object.fromEntries(
			Object.entries(value as Record<string, unknown>)
				.filter(([, entry]) => entry !== undefined)
				.sort(([left], [right]) => left.localeCompare(right))
				.map(([key, entry]) => [key, canonicalValue(entry)]),
		);
	}
	return String(value);
}

export function canonicalJson(value: unknown): string {
	return JSON.stringify(canonicalValue(value));
}

function hmac(key: string, value: string): string {
	return createHmac("sha256", key).update(value).digest("hex");
}

function firstByteDifference(left: string, right: string): number | null {
	const a = Buffer.from(left);
	const b = Buffer.from(right);
	const length = Math.min(a.length, b.length);
	for (let index = 0; index < length; index++) {
		if (a[index] !== b[index]) return index;
	}
	return a.length === b.length ? null : length;
}

function payloadSegments(payload: unknown): { system: unknown; tools: unknown; messages: unknown[]; rest: unknown } {
	if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
		return { system: null, tools: [], messages: [], rest: payload };
	}
	const record = payload as Record<string, unknown>;
	const rawMessages = Array.isArray(record.messages)
		? record.messages
		: Array.isArray(record.input)
			? record.input
			: [];
	// Chat-completions adapters send the system prompt as role "system", or "developer" for
	// reasoning models; both are the stable prefix, not conversation history.
	const isSystemMessage = (entry: unknown): boolean => {
		const role = entry && typeof entry === "object" ? (entry as Record<string, unknown>).role : undefined;
		return role === "system" || role === "developer";
	};
	const systemMessages = rawMessages.filter(isSystemMessage);
	const messages = rawMessages.filter((entry) => !isSystemMessage(entry));
	const system = record.system ?? record.instructions ?? systemMessages;
	const tools = record.tools ?? [];
	const rest = Object.fromEntries(
		Object.entries(record).filter(([key]) => !["system", "instructions", "messages", "input", "tools"].includes(key)),
	);
	return { system, tools, messages, rest };
}

export function observeProviderPayload(
	payload: unknown,
	key: string,
	previous?: ProviderPayloadObservation,
): ProviderPayloadObservation {
	const segments = payloadSegments(payload);
	const systemJson = canonicalJson(segments.system);
	const toolsJson = canonicalJson(segments.tools);
	const messageJson = segments.messages.map(canonicalJson);
	const fullJson = canonicalJson(payload);
	const systemHash = hmac(key, systemJson);
	const toolsHash = hmac(key, toolsJson);
	const messageHashes = messageJson.map((message) => hmac(key, message));
	const fullPayloadHash = hmac(key, fullJson);
	const compactedMessages = segments.messages.filter(containsCompactionSummary);
	const ordinaryMessages = segments.messages.filter((message) => !containsCompactionSummary(message));
	let firstDivergentSegment: ProviderPayloadObservation["firstDivergentSegment"] = null;
	let firstDivergentMessageIndex: number | null = null;
	let firstDivergentByteOffset: number | null = null;
	if (previous) {
		const previousSnapshot = (previous as ObservationWithSnapshot)[PAYLOAD_SNAPSHOT];
		if (previous.systemHash !== systemHash) {
			firstDivergentSegment = "system";
			firstDivergentByteOffset = previousSnapshot ? firstByteDifference(previousSnapshot.systemJson, systemJson) : null;
		} else if (previous.toolsHash !== toolsHash) {
			firstDivergentSegment = "tools";
			firstDivergentByteOffset = previousSnapshot ? firstByteDifference(previousSnapshot.toolsJson, toolsJson) : null;
		} else {
			const max = Math.max(previous.messageHashes.length, messageHashes.length);
			for (let index = 0; index < max; index++) {
				if (previous.messageHashes[index] === messageHashes[index]) continue;
				firstDivergentSegment = "messages";
				firstDivergentMessageIndex = index;
				const previousJson = previousSnapshot?.messageJson[index] ?? "";
				const currentJson = messageJson[index] ?? "";
				firstDivergentByteOffset = previousSnapshot ? firstByteDifference(previousJson, currentJson) : null;
				break;
			}
			if (!firstDivergentSegment && previous.fullPayloadHash !== fullPayloadHash) {
				firstDivergentSegment = "payload";
				firstDivergentByteOffset = previousSnapshot ? firstByteDifference(previousSnapshot.fullJson, fullJson) : null;
			}
		}
	}
	const observation: ObservationWithSnapshot = {
		systemHash,
		toolsHash,
		messageHashes,
		fullPayloadHash,
		firstDivergentSegment,
		firstDivergentMessageIndex,
		firstDivergentByteOffset,
		tokenEstimate: {
			system: tokenEstimate(segments.system),
			tools: tokenEstimate(segments.tools),
			compactedHistory: compactedMessages.reduce<number>((sum, message) => sum + tokenEstimate(message), 0),
			messages: ordinaryMessages.reduce<number>((sum, message) => sum + tokenEstimate(message), 0),
		},
	};
	Object.defineProperty(observation, PAYLOAD_SNAPSHOT, {
		value: { systemJson, toolsJson, messageJson, fullJson } satisfies PayloadSnapshot,
		enumerable: false,
	});
	return observation;
}

export function makeCachePayloadObserverExtension(
	key: string,
	onObservation: (observation: ProviderPayloadObservation) => void,
): InlineExtension {
	let previous: ProviderPayloadObservation | undefined;
	return {
		name: "tg-cache-observer",
		hidden: true,
		factory: (pi) => {
			pi.on("before_provider_request", (event) => {
				const observation = observeProviderPayload(event.payload, key, previous);
				previous = observation;
				onObservation(observation);
			});
		},
	};
}

// Golden hashes lock the cache-visible protocol (docs/cache.md). A failure means the provider
// prefix changed: confirm it is intended, bump CACHE_SCHEMA_VERSION, then update GOLDEN.

import { expect, test } from "bun:test";

// bun test forces UTC; the daemon serializes in local time. Pin the deployment TZ first.
process.env.TZ = "Asia/Singapore";

import { Database } from "bun:sqlite";
import { readFileSync } from "node:fs";
import { serializeMessageEvents, type MessageRow } from "../src/agent/serialize.ts";
import {
	buildSystemPrompt,
	sha256Short,
	CACHE_SCHEMA_VERSION,
	COMPACTION_SUMMARY_PROMPT,
	TELEGRAM_TURN_PROMPT,
	REPLY_RECOVERY_PROMPT,
	toolCapabilityDeclaration,
} from "../src/agent/prompt.ts";
import { TOOL_DEFS, toolProtocolHash } from "../src/agent/tools.ts";
import { batchStickerCandidates, stickerCatalogPromptBlock } from "../src/media/sticker-catalog.ts";
import {
	NO_SEND_MARKER,
	buildCompactionContent,
	projectTelegramContext,
	serializeCompactionMessages,
	TELEGRAM_CONTEXT_TYPE,
	TELEGRAM_CONTEXT_VERSION,
	TELEGRAM_EXTENSION_ORDER,
} from "../src/agent/extensions/index.ts";

const GOLDEN = {
	schemaVersion: 26,
	systemZhTemplate: "929f455372f8",
	systemEnTemplate: "e3368b9e6674",
	eventSerialize: "a05c0584eb08",
	tools: "d627213eee54",
	compactionPrompt: "04da95f62da0",
	multimodalCompaction: "e2da2b8b68fa",
	replyRecovery: "4fc7e277e338",
	telegramTurn: "43bb809c775c",
	extensionOrder: "e04f7032d531",
	contextProtocol: "2e1c7762b239",
};

const CHAT_ID = -1004402809405;

function schemaDb(): Database {
	const db = new Database(":memory:");
	db.exec(readFileSync("src/db/schema.sql", "utf8"));
	return db;
}

function contextMessage(id: number, providerText: string, stickerCandidates = "", blocks?: unknown[]) {
	return {
		role: "custom",
		customType: TELEGRAM_CONTEXT_TYPE,
		content: providerText,
		display: false,
		timestamp: id,
		details: {
			version: TELEGRAM_CONTEXT_VERSION,
			consumedSeq: id,
			providerText,
			blocks: blocks ?? [{ type: "text", text: providerText }],
			stickerCandidates,
			visibleMessageIds: [id],
			events: [],
		},
	};
}

test("prompt, tool and protocol hashes are stable", () => {
	expect(CACHE_SCHEMA_VERSION).toBe(GOLDEN.schemaVersion);
	const allTools = { send: true, search: true, runJs: true };
	expect(sha256Short(buildSystemPrompt(readFileSync("personas/template.zh.md", "utf8"), allTools))).toBe(
		GOLDEN.systemZhTemplate,
	);
	expect(sha256Short(buildSystemPrompt(readFileSync("personas/template.en.md", "utf8"), allTools))).toBe(
		GOLDEN.systemEnTemplate,
	);
	// A bot is only ever told about the tools it really has.
	const sendOnly = toolCapabilityDeclaration({ send: true, search: false, runJs: false });
	expect(sendOnly).toContain("你有一个工具：send");
	expect(sendOnly).not.toContain("search（");
	expect(sendOnly).toContain("你不能联网搜索");
	expect(toolProtocolHash(TOOL_DEFS)).toBe(GOLDEN.tools);
	expect(sha256Short(COMPACTION_SUMMARY_PROMPT)).toBe(GOLDEN.compactionPrompt);
	expect(sha256Short(REPLY_RECOVERY_PROMPT)).toBe(GOLDEN.replyRecovery);
	expect(sha256Short(TELEGRAM_TURN_PROMPT)).toBe(GOLDEN.telegramTurn);
	expect(sha256Short(JSON.stringify(TELEGRAM_EXTENSION_ORDER))).toBe(GOLDEN.extensionOrder);
	expect(
		sha256Short(
			JSON.stringify({ type: TELEGRAM_CONTEXT_TYPE, version: TELEGRAM_CONTEXT_VERSION, noSend: NO_SEND_MARKER }),
		),
	).toBe(GOLDEN.contextProtocol);
});

test("immutable event serialization grammar is stable", () => {
	const row: MessageRow = {
		chat_id: CHAT_ID,
		message_id: 200,
		date: 1754612345,
		thread_id: null,
		sender_id: 111,
		display_name: "Alice",
		username: "alice",
		sender_tag: null,
		sender_chat: null,
		is_bot: 0,
		text: "original",
		caption: null,
		entities: null,
		rich_message: null,
		reply_to_message_id: null,
		reply_to_sender_id: null,
		quote: null,
		forward_origin: null,
		edit_date: null,
		media: null,
	};
	const event = (ingestSeq: number, kind: string, revision: number, eventDate: number, payload: unknown) =>
		({ ingestSeq, chatId: CHAT_ID, messageId: 200, revision, kind, eventDate, payload }) as never;
	const out = serializeMessageEvents(
		schemaDb(),
		[
			event(1, "message", 0, row.date, row),
			event(2, "edit", 1754612400, 1754612400, { ...row, text: "edited", edit_date: 1754612400 }),
			event(3, "metadata", 1, 1754612401, {
				...row,
				reply_to_message_id: 199,
				reply_to_sender_id: 222,
				reply_snapshot: JSON.stringify({
					display_name: "Bob",
					username: "bob",
					text: "An archived parent whose full text exceeds forty characters: keep this ending.",
					media: null,
				}),
				quote: JSON.stringify({
					text: "A selected quote exceeding the former sixty-character limit: retain the final words.",
				}),
			}),
			event(4, "media_update", 2, 1754612402, { file_unique_id: "u", media_kind: "photo", text: "a cat" }),
		],
		{ visibleIds: new Set() },
	);
	expect(sha256Short(out)).toBe(GOLDEN.eventSerialize);
});

test("summary input keeps image order but never sticker candidates or private reasoning", () => {
	const content = buildCompactionContent(
		[
			contextMessage(12, "photo #12", "must not enter summary", [
				{ type: "text", text: "photo #12" },
				{ type: "image", name: "fixture.png", mime: "image/png" },
			]),
		] as never,
		"previous summary",
		() => ({ type: "image", data: "Zml4dHVyZQ==", mimeType: "image/png" }),
	);
	expect(sha256Short(JSON.stringify(content))).toBe(GOLDEN.multimodalCompaction);
	// A summary that records the bot's guesses turns one misreading into a durable "fact".
	const messages = [
		{
			role: "assistant",
			content: [
				{ type: "thinking", thinking: "speculation-canary" },
				{ type: "toolCall", id: "c1", name: "send", arguments: { message: "public-reply" } },
			],
			timestamp: 1,
		},
	] as never;
	const text = serializeCompactionMessages(messages);
	expect(text).toContain("public-reply");
	expect(text).not.toContain("speculation-canary");
	expect(JSON.stringify(buildCompactionContent(messages, undefined, () => null))).not.toContain("speculation-canary");
});

test("every batch keeps its own sticker note so each request is a strict prefix of the next", () => {
	const projected = projectTelegramContext([
		contextMessage(42, "older-batch", "stale-candidate"),
		contextMessage(43, "newest-batch", "newest-candidate"),
		{
			role: "toolResult",
			toolCallId: "call-1",
			toolName: "send",
			content: [{ type: "text", text: "ok" }],
			details: { sent: [100, 101] },
			isError: false,
			timestamp: 3,
		},
	] as never);
	// Glued to the chat text, the list read as if the last speaker had pasted it.
	expect(projected.map((message: any) => message.content)).toEqual([
		"older-batch",
		"stale-candidate",
		"newest-batch",
		"newest-candidate",
		[{ type: "text", text: "ok sent_message_ids=#100,#101" }],
	]);
	expect(projected[3]).toMatchObject({ role: "custom", customType: "telegram_sticker_candidates" });
});

test("sticker catalog and candidate grammar only expose stickers this bot can send", () => {
	const db = schemaDb();
	const media = db.prepare(
		"INSERT INTO media (file_unique_id, kind, mime, sticker_set, sticker_emoji, vision, short_id) VALUES (?, 'sticker', 'image/webp', ?, ?, ?, ?)",
	);
	const vision = (text: string) => JSON.stringify({ model: "m", kind: "sticker", text, at: 1 });
	media.run("cat-1", "Mikufufu", "😺", vision("得意的赞同，smug/amused"), "s1");
	media.run("cat-2", "Mikufufu", "🐱", null, "s2");
	media.run("cat-b", "Mikufufu", "🅱️", vision("另一个 bot 的映射"), "s3");
	media.run("user-1", null, "😺", vision("emotion-1"), "s4");
	media.run("user-b", null, "🅱️", vision("B only"), "s5");
	const map = db.prepare("INSERT INTO media_file_ids (bot_id, file_id, file_unique_id) VALUES (?, ?, ?)");
	for (const [bot, file] of [
		["A", "cat-1"],
		["A", "cat-2"],
		["B", "cat-b"],
		["A", "user-1"],
		["B", "user-b"],
	])
		map.run(bot, `fid-${file}`, file);
	const message = db.prepare(
		"INSERT INTO messages (chat_id, message_id, date, sender_id, display_name, is_bot, media, first_seen_by) VALUES (?, ?, ?, ?, 'u', 0, ?, 'A')",
	);
	for (const [id, file] of [
		[1, "user-1"],
		[2, "user-b"],
	] as const)
		message.run(
			CHAT_ID,
			id,
			100 + id,
			id,
			JSON.stringify({ kind: "sticker", file_unique_id: file, sticker_emoji: "😺" }),
		);

	expect(stickerCatalogPromptBlock(db, "A", ["Mikufufu"])).toBe(
		"# Sticker 目录\n\ns1: 😺 得意的赞同，smug/amused\ns2: 🐱",
	);
	expect(stickerCatalogPromptBlock(db, "B", ["Mikufufu"])).toBe("# Sticker 目录\n\ns3: 🅱️ 另一个 bot 的映射");
