/** One request deadline across stream creation and consumption. Pi owns all retries. */
import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type AssistantMessageEventStream,
	type Model,
	type RetryPolicy,
} from "@earendil-works/pi-ai";

export function providerRetryPolicy(maxRetries: number): RetryPolicy {
	return { enabled: maxRetries > 0, maxRetries, baseDelayMs: 10_000 };
}

export type GuardedCall = (signal: AbortSignal) => AssistantMessageEventStream | Promise<AssistantMessageEventStream>;

/** Pi recognizes request_too_large, but not a proxy's HTML HTTP 413 response. */
function normalizeRequestSizeError(message: AssistantMessage): AssistantMessage {
	if (
		message.stopReason !== "error" ||
		!/\b(?:HTTP\s+413|413\s+(?:Request Entity Too Large|Payload Too Large)|request entity too large|payload too large)\b/i.test(
			message.errorMessage ?? "",
		)
	)
		return message;
	return { ...message, errorMessage: "request_too_large: provider request exceeds transport size limit" };
}

function failure(model: Model<Api>, stopReason: "error" | "aborted", errorMessage: string): AssistantMessage {
	return {
		role: "assistant",
		content: [],
		api: model.api,
		provider: model.provider,
		model: model.id,
		usage: {
			input: 0,
			output: 0,
			cacheRead: 0,
			cacheWrite: 0,
			totalTokens: 0,
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
		},
		stopReason,
		errorMessage,
		timestamp: Date.now(),
	};
}

/** Never repeats a request; even an uncooperative provider cannot hold the consumer open. */
export function guardProviderCall(
	call: GuardedCall,
	model: Model<Api>,
	callerSignal: AbortSignal | undefined,
	options: { timeoutMs: number },
): AssistantMessageEventStream {
	const output = createAssistantMessageEventStream();
	const controller = new AbortController();
	let finished = false;
	const cleanup = () => {
		finished = true;
		clearTimeout(timer);
		callerSignal?.removeEventListener("abort", cancel);
	};
	const fail = (reason: "error" | "aborted", message: string) => {
		if (finished) return;
		cleanup();
		const result = normalizeRequestSizeError(failure(model, reason, message));
		output.push({ type: "error", reason, error: result });
		output.end(result);
		controller.abort();
	};
	const cancel = () => fail("aborted", "provider call aborted");
	const timer = setTimeout(() => fail("error", "provider_timeout: request deadline exceeded"), options.timeoutMs);
	callerSignal?.addEventListener("abort", cancel, { once: true });
	if (callerSignal?.aborted) cancel();
	void (async () => {
		try {
			if (finished) return;
			const stream = await call(controller.signal);
			for await (const event of stream) {
				if (finished) return;
				output.push(event.type === "error" ? { ...event, error: normalizeRequestSizeError(event.error) } : event);
				if (event.type === "done" || event.type === "error") {
					cleanup();
					output.end();
					return;
				}
			}
			if (!finished) {
				const result = await stream.result();
				if (finished) return;
				cleanup();
				output.end(normalizeRequestSizeError(result));
			}
		} catch (error) {
			fail("error", error instanceof Error ? error.message : "provider request failed");
		}
	})();
	return output;
}

import type { AgentMessage } from "@earendil-works/pi-agent-core";
import type {
	AgentActivity,
	AgentActivityAssistantSection,
	AgentActivityEventSection,
	AgentActivitySection,
} from "../ipc.ts";

export const AGENT_ACTIVITY_MAX_SECTIONS = 64;
export const AGENT_ACTIVITY_MAX_CHARS = 512 * 1024;

function take(value: string, limit: number): { value: string; complete: boolean } {
	if (value.length <= limit) return { value, complete: true };
	if (limit <= 0) return { value: "", complete: false };
	return { value: `${value.slice(0, Math.max(0, limit - 1))}…`, complete: false };
}

function assistantSection(
	message: Extract<AgentMessage, { role: "assistant" }>,
	limit: number,
): { section: AgentActivityAssistantSection | null; chars: number; complete: boolean } {
	let remaining = limit;
	let complete = true;
	const content: AgentActivityAssistantSection["content"] = [];
	for (const block of message.content) {
		if (block.type !== "text" && block.type !== "thinking") continue;
		const source = block.type === "text" ? block.text : block.thinking;
		if (!source.trim()) continue;
		const result = take(source, remaining);
		if (result.value) {
			content.push(
				block.type === "text" ? { type: "text", text: result.value } : { type: "thinking", thinking: result.value },
			);
			remaining -= result.value.length;
		}
		if (!result.complete) {
			complete = false;
			break;
		}
	}
	return {
		section: content.length > 0 ? { type: "assistant", content, stopReason: message.stopReason } : null,
		chars: limit - remaining,
		complete,
	};
}

/** Collects one bounded UI projection without becoming business or provider state. */
export class AgentActivityCollector {
	private readonly sections: AgentActivitySection[] = [];
	private chars = 0;
	private truncated = false;

	constructor(
		readonly activityId: string,
		readonly startedAt: number,
	) {}

	captureAssistant(message: Extract<AgentMessage, { role: "assistant" }>): void {
		if (!this.canAppend()) return;
		const projected = assistantSection(message, AGENT_ACTIVITY_MAX_CHARS - this.chars);
		if (projected.section) {
			this.sections.push(projected.section);
			this.chars += projected.chars;
		}
		if (!projected.complete) this.truncated = true;
	}

	captureEvent(kind: string, payload: unknown): void {
		if (!this.canAppend()) return;
		const serialized = JSON.stringify(payload ?? null);
		const projected = take(serialized, AGENT_ACTIVITY_MAX_CHARS - this.chars);
		const section: AgentActivityEventSection = { type: "event", kind, detail: projected.value };
		this.sections.push(section);
		this.chars += projected.value.length;
		if (!projected.complete) this.truncated = true;
	}

	snapshot(partial?: Extract<AgentMessage, { role: "assistant" }> | null): AgentActivity {
		const sections = [...this.sections];
		let truncated = this.truncated;
		if (partial) {
			if (sections.length >= AGENT_ACTIVITY_MAX_SECTIONS) truncated = true;
			else {
				const projected = assistantSection(partial, AGENT_ACTIVITY_MAX_CHARS - this.chars);
				if (projected.section) sections.push(projected.section);
				if (!projected.complete) truncated = true;
			}
		}
		return {
			version: 1,
			activityId: this.activityId,
			startedAt: this.startedAt,
			sections,
			truncated,
		};
	}

	private canAppend(): boolean {
		if (this.sections.length >= AGENT_ACTIVITY_MAX_SECTIONS || this.chars >= AGENT_ACTIVITY_MAX_CHARS) {
			this.truncated = true;
			return false;
		}
		return true;
	}
}

import { randomUUID } from "node:crypto";
import { renameSync, rmSync, writeFileSync } from "node:fs";
import { SessionManager, type SessionEntry } from "@earendil-works/pi-coding-agent";

/**
 * Pi session files only grow: everything before the latest compaction's kept window is dead for
 * the provider but is still parsed and held in memory on every start. On resume, rewrite the file
 * with just the live window (plus the latest model / thinking-level entries Pi derives settings
 * from), keeping the same session id. The rewrite is only installed when Pi builds a byte-identical
 * context from it; the original file is kept beside it as `<file>.pre-trim-<time>`.
 */
export function trimSessionBeforeCompaction(sessionFile: string, sessionDir: string, cwd: string): boolean {
	const source = SessionManager.open(sessionFile, sessionDir, cwd);
	const branch = source.getBranch();
	const compaction = branch.findLast((entry) => entry.type === "compaction");
	if (!compaction) return false;
	const firstKept = branch.findIndex((entry) => entry.id === compaction.firstKeptEntryId);
	if (firstKept <= 0) return false;
	const dropped = branch.slice(0, firstKept);
	const settings = (["model_change", "thinking_level_change"] as const)
		.map((type) => dropped.findLast((entry) => entry.type === type))
		.filter((entry): entry is SessionEntry => entry != null);
	// Already trimmed: only the carried-over settings precede the kept window.
	if (dropped.length === settings.length) return false;
	let parentId: string | null = null;
	const entries = [...settings, ...branch.slice(firstKept).filter((entry) => entry.type !== "label")].map((entry) => {
		const rechained = { ...entry, parentId };
		parentId = entry.id;
		return rechained;
	});
	const temporary = `${sessionFile}.trim-${randomUUID()}`;
	writeFileSync(temporary, [source.getHeader(), ...entries].map((line) => `${JSON.stringify(line)}\n`).join(""), {
		flag: "wx",
		mode: 0o600,
	});
	const trimmed = SessionManager.open(temporary, sessionDir, cwd);
	if (JSON.stringify(trimmed.buildSessionContext()) !== JSON.stringify(source.buildSessionContext())) {
		rmSync(temporary, { force: true });
		return false;
	}
	renameSync(sessionFile, `${sessionFile}.pre-trim-${new Date().toISOString().replace(/[:.]/g, "-")}`);
	renameSync(temporary, sessionFile);
	return true;
}

