// Structured context ownership walker: recover the SQLite half of prior custom-message
// commits from session entries. Provider-rendered strings are never parsed for identities.
//
// Visibility semantics: every walk input (startup reconcile over buildContextEntries(),
// handleBeforeCompact over keptEntries) is the active window after the last compaction
// boundary, so the union of custom_message visibleMessageIds inside the window is the true
// visible set. Compaction entries only carry the monotonic cursor forward: their
// details.visibleMessageIds is the cumulative union computed by this same walker, so
// re-adding it could never shrink the set (RC1 phantom visibility).

import type { SessionEntry } from "@earendil-works/pi-coding-agent";
import { isTelegramContextDetails } from "./extensions/index.ts";

export interface ContextState {
	consumedSeq: number;
	visible: Set<number>;
}

export function contextStateFromEntries(entries: readonly SessionEntry[], initialConsumedSeq = 0): ContextState {
	let consumedSeq = initialConsumedSeq;
	const visible = new Set<number>();
	for (const entry of entries) {
		if (entry.type === "custom_message" && isTelegramContextDetails(entry.details)) {
			consumedSeq = Math.max(consumedSeq, entry.details.consumedSeq);
			for (const messageId of entry.details.visibleMessageIds) visible.add(messageId);
			continue;
		}
		if (entry.type === "compaction") {
			// Compaction is a replacement boundary, but its details.visibleMessageIds is the
			// cumulative union computed by this same walker, so re-adding it would never shrink
			// the visible set. Only the monotonic cursor is carried forward; visibility comes
			// from the custom_message entries inside the active window after the boundary.
			const details = entry.details as { consumedSeq?: unknown } | undefined;
			if (Number.isSafeInteger(details?.consumedSeq))
				consumedSeq = Math.max(consumedSeq, details!.consumedSeq as number);
			continue;
		}
		if (entry.type === "message" && entry.message.role === "toolResult" && entry.message.toolName === "send") {
			const sent = (entry.message.details as { sent?: unknown } | undefined)?.sent;
			if (Array.isArray(sent)) {
				for (const messageId of sent) {
					if (Number.isSafeInteger(messageId) && (messageId as number) > 0) visible.add(messageId as number);
				}
			}
		}
	}
	return { consumedSeq, visible };
}

import { getAgentDir, SettingsManager } from "@earendil-works/pi-coding-agent";
import type { ThinkingLevel } from "@earendil-works/pi-agent-core";

const THINKING_LEVELS = new Set<ThinkingLevel>(["off", "minimal", "low", "medium", "high", "xhigh", "max"]);

export interface PiModelDefaults {
	provider: string | undefined;
	model: string | undefined;
	thinkingLevel: ThinkingLevel;
}

export class PiSettingsConfigurationError extends Error {
	readonly category = "invalid_settings" as const;

	constructor(readonly scopes: readonly ("global" | "project")[]) {
		super(
			`Pi settings unavailable (invalid_settings: ${scopes.join(",") || "unknown"}). Fix Pi settings, then restart.`,
		);
		this.name = "PiSettingsConfigurationError";
	}
}

/** Read Pi's merged global/project defaults without copying or exposing credential data. */
export function loadPiModelDefaults(projectRoot: string, agentDir = getAgentDir()): PiModelDefaults {
	const settings = SettingsManager.create(projectRoot, agentDir);
	const loadErrors = settings.drainErrors();
	if (loadErrors.length > 0) {
		throw new PiSettingsConfigurationError([...new Set(loadErrors.map((error) => error.scope))]);
	}

	return {
		provider: settings.getDefaultProvider(),
		model: settings.getDefaultModel(),
		// This is Pi's own SDK fallback when defaultThinkingLevel is absent.
		thinkingLevel: settings.getDefaultThinkingLevel() ?? "medium",
	};
}

export function isPiThinkingLevel(value: unknown): value is ThinkingLevel {
	return typeof value === "string" && THINKING_LEVELS.has(value as ThinkingLevel);
}

export const DEFAULT_COMPACTION_MODEL = "openai-codex/gpt-5.6-luna:low";
export const DEFAULT_AUXILIARY_VISUAL_MODEL = DEFAULT_COMPACTION_MODEL;

const REQUEST_THINKING_LEVELS = ["minimal", "low", "medium", "high", "xhigh", "max"] as const;

export type PiRequestThinkingLevel = (typeof REQUEST_THINKING_LEVELS)[number];

export interface PiModelReference {
	provider: string;
	model: string;
	thinkingLevel: PiRequestThinkingLevel;
	canonical: string;
}

/** Parse a task model reference without consulting Pi's catalog or credential store. */
export function parsePiModelReference(value: string): PiModelReference | null {
	if (value !== value.trim() || /[\u0000-\u001f\u007f]/.test(value)) return null;
	const slash = value.indexOf("/");
	const colon = value.lastIndexOf(":");
	if (slash <= 0 || colon <= slash + 1 || colon === value.length - 1) return null;

	const provider = value.slice(0, slash);
	const model = value.slice(slash + 1, colon);
	const thinkingLevel = value.slice(colon + 1);
	if (!provider || !model || /[\s/:]/.test(provider) || /\s/.test(model)) return null;
	if (!(REQUEST_THINKING_LEVELS as readonly string[]).includes(thinkingLevel)) return null;

	return {
		provider,
		model,
		thinkingLevel: thinkingLevel as PiRequestThinkingLevel,
		canonical: `${provider}/${model}:${thinkingLevel}`,
	};
}

export function canonicalPiModelReference(value: string): string | null {
	return parsePiModelReference(value)?.canonical ?? null;
}

import { createHash } from "node:crypto";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { BotConfig } from "../config.ts";
import type { InlineKeyboardMarkup } from "./api.ts";

const PAGE_SIZE = 8;

/** Stable, bounded callback identities also work after a daemon restart or catalog reorder. */
export function modelMenuKey(provider: string, model?: string): string {
	return createHash("sha256")
		.update(JSON.stringify([provider, model ?? null]))
		.digest("hex")
		.slice(0, 24);
}

export interface ModelMenuView {
	text: string;
	replyMarkup: InlineKeyboardMarkup;
}

export function renderModelMenu(
	bot: BotConfig,
	models: readonly Model<Api>[],
	data = "model:r:0",
): ModelMenuView | null {
	const root = /^model:r:(\d{1,6})$/.exec(data);
	const providerPage = /^model:p:([a-f0-9]{24}):(\d{1,6})$/.exec(data);
	if (!root && !providerPage) return null;
	const providers = [...new Set(models.map((model) => model.provider))].sort();
	const provider = providerPage ? providers.find((id) => modelMenuKey(id) === providerPage[1]) : undefined;
	if (providerPage && !provider) return null;
	const page = Number(root?.[1] ?? providerPage![2]);
	const choices = provider
		? models
				.filter((model) => model.provider === provider)
				.sort((a, b) => a.id.localeCompare(b.id))
				.map((model) => ({
					text: `${bot.provider === model.provider && bot.model === model.id ? "✓ " : ""}${model.id}`,
					callback_data: `model:s:${modelMenuKey(model.provider, model.id)}`,
				}))
		: providers.map((id) => ({ text: id, callback_data: `model:p:${modelMenuKey(id)}:0` }));
	const pages = Math.max(1, Math.ceil(choices.length / PAGE_SIZE));
	if (page >= pages) return null;
	const rows = choices.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE).map((button) => [button]);
	const prefix = provider ? `model:p:${modelMenuKey(provider)}` : "model:r";
	const navigation = [];
	if (page > 0) navigation.push({ text: "‹ 上一页", callback_data: `${prefix}:${page - 1}` });
	if (page + 1 < pages) navigation.push({ text: "下一页 ›", callback_data: `${prefix}:${page + 1}` });
	if (navigation.length) rows.push(navigation);
	if (provider) rows.push([{ text: "‹ 提供商", callback_data: "model:r:0" }]);
	return {
		text: [
			`${bot.name} · 模型选择`,
			`当前：${bot.provider}/${bot.model}（${bot.reasoningEffort}）`,
			choices.length
				? `${provider ?? "请选择提供商"} · ${page + 1}/${pages}`
				: "Pi 暂无可用模型，请先在 Pi 中完成 /login。",
			"选择后立即保存并开启新会话；忙碌时请稍后重试。",
			"Reasoning 尽量沿用当前档位，不支持时按模型能力调整并显示结果。",
		].join("\n"),
		replyMarkup: { inline_keyboard: rows },
	};
}
